from collections import deque
def reach(g, s):
    seen = [False] * len(g)
    seen[s] = True
    q = deque([s])
    while q:
        x = q.popleft()
        for y in g[x]:
            if not seen[y]:
                seen[y] = ___
                q.append(y)
    return sum(seen)

static int reach(int[][] g, int s) {
    boolean[] seen = new boolean[g.length];
    seen[s] = true;
    var q = new ArrayDeque<>(List.of(s));
    int cnt = 1;
    while (!q.isEmpty())
        for (int y : g[q.poll()])
            if (!seen[y]) {
                seen[y] = ___; cnt++; q.add(y);
            }
    return cnt;
}

function reach(g, s) {
  const seen = Array(g.length).fill(false);
  seen[s] = true;
  const q = [s];
  for (let h = 0; h < q.length; h++) {
    for (const y of g[q[h]]) {
      if (seen[y]) continue;
      seen[y] = ___; q.push(y);
    }
  }
  return q.length;
}

int reach(const vector<vector<int>>& g, int s) {
    vector<bool> seen(g.size()); seen[s] = true;
    queue<int> q({s});
    while (!q.empty()) {
        int x = q.front(); q.pop();
        for (int y : g[x])
            if (!seen[y]) {
                seen[y] = ___; q.push(y);
            }
    }
    return count(begin(seen), end(seen), true);
}

